// lib/content.ts — Build-time static content loader and Markdown renderer.
// Reads content/manifest.json and Markdown files generated by scripts/sync_docs.py
// so Next.js emits 100% static HTML pages with zero runtime network requests.

import fs from "fs";
import path from "path";

export type DocTrack = "docs" | "guides";

export interface TocItem {
	level: number;
	text: string;
	id: string;
}

export interface DocPageMeta {
	slug: string;
	track: DocTrack;
	title: string;
	sourcePath: string;
	sourceBranch: string;
	localFile: string;
	toc: TocItem[];
}

export interface ProjectRecord {
	id: string;
	name: string;
	repo: string;
	repoUrl: string;
	branch: string;
	established: boolean;
	status: string;
	version: string;
	badge: string;
	rebaseNotice: string | null;
	description: string;
	tracks: DocTrack[];
	syncedSha: string | null;
	pages: DocPageMeta[];
}

export interface DocsManifest {
	generatedAt: string;
	license: {
		name: string;
		fullName: string;
		url: string;
		summary: string;
	};
	projects: ProjectRecord[];
}

const CONTENT_ROOT = path.join(process.cwd(), "content");
const MANIFEST_PATH = path.join(CONTENT_ROOT, "manifest.json");

/** Load the build-time compiled manifest generated by scripts/sync_docs.py. */
export function loadManifest(): DocsManifest {
	const raw = fs.readFileSync(MANIFEST_PATH, "utf-8");
	return JSON.parse(raw) as DocsManifest;
}

/** Find a project by its slug ID. */
export function getProject(projectId: string): ProjectRecord | undefined {
	return loadManifest().projects.find((p) => p.id === projectId);
}

/** Read the raw Markdown string for a static doc or guide page. */
export function readPageMarkdown(localFile: string): string {
	const absPath = path.join(process.cwd(), localFile);
	if (!fs.existsSync(absPath)) {
		return "# Page Not Found\n\nThis static page has not been generated yet.";
	}
	return fs.readFileSync(absPath, "utf-8");
}

/** Escape HTML special characters before injecting into rendered markup. */
function escapeHtml(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

/** Convert a heading string into a URL anchor slug matching sync_docs.py. */
function slugify(value: string): string {
	return (
		value
			.replace(/[^a-zA-Z0-9\s-]/g, "")
			.trim()
			.toLowerCase()
			.replace(/[\s_-]+/g, "-") || "section"
	);
}

/** Format inline Markdown tokens (code, bold, italic, links). */
function renderInline(text: string): string {
	let out = escapeHtml(text);
	out = out.replace(/`([^`]+)`/g, "<code>$1</code>");
	out = out.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
	out = out.replace(/\*([^*]+)\*/g, "<em>$1</em>");
	out = out.replace(
		/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,
		'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>',
	);
	return out;
}

/**
 * Dependency-free static Markdown-to-HTML renderer for build-time pages.
 * Supports headings (with anchor IDs), fenced code blocks, lists, callouts,
 * and paragraphs cleanly without shipping a runtime parser to the browser.
 */
export function renderMarkdown(markdown: string): string {
	const lines = markdown.replace(/\r\n/g, "\n").split("\n");
	const html: string[] = [];
	let inCode = false;
	let codeLang = "";
	let codeLines: string[] = [];
	let inList = false;

	const flushList = () => {
		if (inList) {
			html.push("</ul>");
			inList = false;
		}
	};

	for (const line of lines) {
		if (line.startsWith("```")) {
			flushList();
			if (!inCode) {
				inCode = true;
				codeLang = line.slice(3).trim() || "text";
				codeLines = [];
			} else {
				const codeText = escapeHtml(codeLines.join("\n"));
				html.push(
					`<div class="kd-code-wrap" data-lang="${escapeHtml(codeLang)}">` +
						`<div class="kd-code-head"><span>${escapeHtml(codeLang)}</span>` +
						`<button type="button" class="kd-copy-btn" data-copy="true">Copy</button></div>` +
						`<pre><code>${codeText}</code></pre></div>`,
				);
				inCode = false;
			}
			continue;
		}

		if (inCode) {
			codeLines.push(line);
			continue;
		}

		const headingMatch = line.match(/^(#{1,3})\s+(.+)$/);
		if (headingMatch) {
			flushList();
			const level = headingMatch[1].length;
			const rawHeading = headingMatch[2].trim();
			const id = slugify(rawHeading.replace(/`([^`]+)`/g, "$1"));
			html.push(`<h${level} id="${id}">${renderInline(rawHeading)}</h${level}>`);
			continue;
		}

		if (line.startsWith("> ")) {
			flushList();
			html.push(`<blockquote class="kd-callout">${renderInline(line.slice(2))}</blockquote>`);
			continue;
		}

		const listMatch = line.match(/^[-*]\s+(.+)$/);
		if (listMatch) {
			if (!inList) {
				html.push("<ul>");
				inList = true;
			}
			html.push(`<li>${renderInline(listMatch[1])}</li>`);
			continue;
		}

		if (line.trim() === "") {
			flushList();
			continue;
		}

		flushList();
		html.push(`<p>${renderInline(line)}</p>`);
	}

	flushList();
	return html.join("\n");
}
